default.shell:
$mismatchCount = 0

$key = Get-Item -LiteralPath 'HKLM:\Software\Microsoft\Windows\CurrentVersion\Policies\LAPS' -ErrorAction SilentlyContinue
$current = $null
if ($key) { $current = $key.GetValue('PasswordComplexity', $null, 'DoNotExpandEnvironmentNames') }
if (-not ($current -is [int] -and [BitConverter]::ToUInt32([BitConverter]::GetBytes($current), 0) -eq [uint32]4)) {
    Write-Output 'Mismatch: HKLM:\Software\Microsoft\Windows\CurrentVersion\Policies\LAPS [PasswordComplexity]'
    $mismatchCount++
}

if ($mismatchCount -gt 0) { exit 1 }
exit 0

---

{{ if .Vars.win11cis_level_1 }}
  {{ if .Vars.win11cis_rule_18_9_25_4 }}
    {{ if .Vars.win11cis_domain_joined }}
registry:
  HKLM\SOFTWARE\Microsoft\Windows\CurrentVersion\Policies\LAPS\PasswordComplexity:
    title: "18.9.25.4 | Ensure 'Password Settings: Password Complexity' is set to 'Enabled: Large letters + small letters + numbers + special characters' | PasswordComplexity"
    exists: true
    value: 4
    type: REG_DWORD
    meta:
      workstation: 1
      CIS_ID:
        - 18.9.25.4
      NIST800-53R5:
        - IA-5(1)
    {{ end }}
  {{ end }}
{{ end }}

steps.shell:
$ErrorActionPreference = 'Stop'
trap { Write-Output $_.Exception.Message; exit 1 }

if (-not (Test-Path -LiteralPath 'HKLM:\Software\Microsoft\Windows\CurrentVersion\Policies\LAPS')) {
    New-Item -Path 'HKLM:\Software\Microsoft\Windows\CurrentVersion\Policies\LAPS' -Force | Out-Null
}
New-ItemProperty -LiteralPath 'HKLM:\Software\Microsoft\Windows\CurrentVersion\Policies\LAPS' -Name 'PasswordComplexity' -Value 4 -PropertyType DWord -Force | Out-Null
exit 0
